<?php require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';$message='Jika akun tersebut tersedia, token reset telah dibuat.';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim($_POST['username']??'');$q=$pdo->prepare('SELECT id FROM admin_users WHERE username=? AND active=1');$q->execute([$username]);if($id=$q->fetchColumn()){$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO admin_password_resets(admin_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$id,hash('sha256',$token)]);$_SESSION['reset_token_once']=$token;$message='Token reset untuk instalasi lokal ditampilkan di bawah.';}}$token=$_SESSION['reset_token_once']??'';unset($_SESSION['reset_token_once']);?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pemulihan admin</title><link rel="stylesheet" href="../assets/style.css"></head><body><form class="panel adminlogin" method="post"><h1>Pemulihan akses admin</h1><p><?=e($message)?></p><?php if($token):?><p><b>Token lokal (berlaku 30 menit):</b><br><code><?=e($token)?></code><br><a href="reset-password.php?token=<?=urlencode($token)?>">Lanjutkan reset</a></p><?php endif?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Nama pengguna</label><input name="username" required></div><button class="btn full">Buat token reset</button><p><a href="login.php">Kembali ke login</a></p></form></body></html>